function throttle(fn, wait) {
  var last = 0;
  var timer;
  var savedArgs;
  var savedThis;
  return function () {
    var now = Date.now();
    savedArgs = arguments;
    savedThis = this;
    var remain = wait - (now - last);
    if (remain <= 0) {
      clearTimeout(timer);
      timer = null;
      last = now;
      fn.apply(savedThis, savedArgs);
    } else if (!timer) {
      timer = setTimeout(function () {
        last = Date.now();
        timer = null;
        fn.apply(savedThis, savedArgs);
      }, remain);
    }
  };
}

