function reduce(list, fn, initial) {
  var i = 0;
  var acc;
  if (arguments.length < 3) {
    if (list.length === 0) throw new TypeError("Reduce of empty array with no initial value");
    acc = list[0];
    i = 1;
  } else {
    acc = initial;
  }
  for (; i < list.length; i++) acc = fn(acc, list[i], i);
  return acc;
}

