function flat(list, depth) {
  if (depth === undefined) depth = 1;
  var out = [];
  function walk(items, left) {
    for (var i = 0; i < items.length; i++) {
      if (Array.isArray(items[i]) && left > 0) walk(items[i], left - 1);
      else out.push(items[i]);
    }
  }
  walk(list, depth);
  return out;
}

