function deepClone(value, seen) {
  if (value === null || typeof value !== "object") return value;
  if (!seen) seen = new WeakMap();
  if (seen.has(value)) return seen.get(value);
  if (Object.prototype.toString.call(value) === "[object Date]") return new Date(value.getTime());
  var out = Array.isArray(value) ? [] : {};
  seen.set(value, out);
  if (Array.isArray(value)) {
    for (var i = 0; i < value.length; i++) out.push(deepClone(value[i], seen));
    return out;
  }
  var keys = Object.keys(value);
  for (var k = 0; k < keys.length; k++) out[keys[k]] = deepClone(value[keys[k]], seen);
  return out;
}

