function deepEqual(a, b, seen) {
  if (Object.is(a, b)) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  if (!seen) seen = new WeakMap();
  if (seen.get(a) === b) return true;
  seen.set(a, b);
  var tagA = Object.prototype.toString.call(a);
  var tagB = Object.prototype.toString.call(b);
  if (tagA !== tagB) return false;
  if (tagA === "[object Date]") return a.getTime() === b.getTime();
  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (var i = 0; i < a.length; i++) if (!deepEqual(a[i], b[i], seen)) return false;
    return true;
  }
  var keys = Object.keys(a);
  if (keys.length !== Object.keys(b).length) return false;
  for (var k = 0; k < keys.length; k++) {
    if (!Object.prototype.hasOwnProperty.call(b, keys[k])) return false;
    if (!deepEqual(a[keys[k]], b[keys[k]], seen)) return false;
  }
  return true;
}

