solution:
function pool(limit, tasks) {
  var results = new Array(tasks.length);
  var next = 0;
  var running = 0;
  return new Promise(function (resolve, reject) {
    if (tasks.length === 0) { resolve(results); return; }
    var failed = false;
    function launch() {
      if (failed) return;
      if (next >= tasks.length && running === 0) { resolve(results); return; }
      while (running < limit && next < tasks.length) {
        (function (index) {
          running += 1;
          Promise.resolve().then(tasks[index]).then(function (value) {
            results[index] = value;
            running -= 1;
            launch();
          }, function (error) {
            failed = true;
            reject(error);
          });
        })(next);
        next += 1;
      }
    }
    launch();
  });
}
